import android.graphics.Paint

/**
 * ইমোজি প্যানেলের ক্যাটাগরি।
 * Unicode-এর সব স্ট্যান্ডার্ড ইমোজি (স্মাইলি, মানুষ, প্রাণী, খাবার, অ্যাক্টিভিটি, ভ্রমণ, বস্তু, চিহ্ন, পতাকা)
 * এবং সাথে Aesthetic ইমোজি, সাজানোর চিহ্ন ও কাওমোজি।
 * যে ইমোজি ফোনের ফন্টে নেই (বাক্স দেখাত), সেগুলো আপনাআপনি বাদ পড়ে।
 */
object EmojiData {
    class Cat(
        val icon: String,
        private val raw: String,
        val cols: Int = 8,
        val textSize: Float = 24f,
        private val sep: Char = ' '
    ) {
        private var cache: List<String>? = null

        /** ফোনে যেগুলো সত্যিই দেখানো যায় শুধু সেগুলো। */
        fun items(): List<String> {
            cache?.let { return it }
            val all = raw.split(sep).filter { it.isNotEmpty() }
            val ok = all.filter { EmojiData.supported(it) }
            val res = if (ok.isEmpty()) all else ok
            cache = res
            return res
        }
    }

    private val paint = Paint()
    private val glyphCache = HashMap<String, Boolean>()

    /** এই ইমোজি/চিহ্ন ফোনের ফন্টে আছে কি না। */
    fun supported(s: String): Boolean {
        glyphCache[s]?.let { return it }
        val ok = try { paint.hasGlyph(s) } catch (e: Throwable) { true }
        glyphCache[s] = ok
        return ok
    }

